insert into public.board_bodies (id, name, sort) values ('direcao','Direção',1),('assembleia','Assembleia Geral',2),('fiscal','Conselho Fiscal',3);
insert into public.news (slug,title,category,cover_url,published_at,body,status) values
  ('renovacao-andre-couto','RENOVAÇÃO · ANDRÉ COUTO','Clube','/assets/c79bcbed7dc7c8c0dba60f90deeda7f8.jpg','2026-06-23','[{"type": "p", "parts": [{"text": "O SF Damaiense tem o orgulho de anunciar a continuidade de André Couto como treinador principal da equipa sénior para a época 2026/27."}]}, {"type": "p", "parts": [{"text": "Ligado ao clube há 9 anos, André Couto representa na perfeição os valores e a identidade do Damaiense, tendo deixado a sua marca tanto como jogador como no papel de treinador."}]}, {"type": "p", "parts": [{"text": "Ao longo deste percurso de dedicação, compromisso e paixão pelo nosso emblema, alcançou este ano um dos momentos mais marcantes da sua caminhada no clube: a conquista da subida de divisão de Juniores para a 1.ªDistrital, resultado do trabalho, união e ambição demonstrados por toda a equipa."}]}, {"type": "p", "parts": [{"text": "A renovação de André Couto reforça a aposta na continuidade de um projeto sólido, assente no conhecimento da casa e na vontade de levar o SF Damaiense cada vez mais longe."}]}, {"type": "p", "parts": [{"text": "Parabéns, Mister! Que a nova época seja repleta de sucessos."}]}]'::jsonb,'published'),
  ('bem-vindos-de-volta-a-casa','Bem-vindos de volta a casa!','Clube','/assets/177e6ac4455c70ec993e8c19024c9402.jpg','2026-06-22','[{"type": "p", "parts": [{"text": "O SF Damaiense tem o enorme prazer de anunciar o regresso de duas figuras que fazem parte da história do nosso clube."}]}, {"type": "p", "parts": [{"text": "Ricardo Pereira “Ricardinho” assume funções como Diretor Desportivo da equipa sénior. Antigo jogador das nossas camadas jovens e da nossa equipa sénior e treinador, regressa a uma casa que bem conhece, trazendo consigo anos de dedicação, experiência e paixão pelo nosso clube"}]}, {"type": "p", "parts": [{"text": "João Coimbra “Chipy” integra a estrutura como Team Manager. Com mais de 15 anos de ligação ao clube, destacou-se como jogador e treinador da nossa formação e equipa sénior, sendo uma referência de compromisso, identidade e espírito damaiense."}]}, {"type": "p", "parts": [{"text": "Dois homens da casa, dois exemplos de dedicação ao nosso emblema, que agora abraçam um novo desafio ao serviço da equipa sénior."}]}, {"type": "p", "parts": [{"text": "Desejamos ‘Chipy’ e ‘Ricardinho’ os maiores sucessos nesta nova etapa."}]}, {"type": "p", "parts": [{"text": "Juntos, continuaremos a construir o futuro do SF Damaiense!"}]}]'::jsonb,'published'),
  ('os-nossos-juniores-sao-de-1a','Os nossos Juniores são de 1.ª!','Formação','/assets/6a42ae5c06b00db2f0423dfd83c83c35.jpg','2026-05-23','[{"type": "p", "parts": [{"text": "É oficial: os nossos Juniores garantiram a subida à 1.ª Divisão! Um feito extraordinário que recompensa o trabalho, a dedicação e o espírito de sacrifício demonstrados ao longo de toda a época."}]}, {"type": "p", "parts": [{"text": "Os nossos jovens atletas demonstraram, dentro e fora de campo, os valores que representam o clube: compromisso, ambição, respeito e paixão pelo futebol. Hoje celebramos uma subida de divisão, mas também o crescimento de um grupo que nunca deixou de acreditar nos seus sonhos."}]}, {"type": "p", "parts": [{"text": "Parabéns Craques!"}]}, {"type": "p", "parts": [{"text": "Os nossos Juniores são de 1.ª!"}]}, {"type": "p", "parts": [{"text": "Parabéns, campeões! O Damaiense orgulha-se de vocês."}]}]'::jsonb,'published'),
  ('novo-coordenador-tecnico-do-damaiense','Novo Coordenador Técnico do Damaiense','Clube','/assets/d6bc4e51f7ba3e1e89682c716576220c.jpg','2026-04-19','[{"type": "p", "parts": [{"text": "O Damaiense tem o prazer de anunciar a nomeação de Pedro Mota como novo Coordenador Técnico do clube."}]}, {"type": "p", "parts": [{"text": "Esta decisão reflete a total confiança na sua competência, no seu percurso e na forma como entende o futebol — assente na ambição, no rigor e no verdadeiro espírito de equipa"}]}, {"type": "p", "parts": [{"text": "Identificado com os valores que orientam o Damaiense — dedicação, compromisso e desenvolvimento integral dos atletas — Pedro Mota assume este desafio com uma visão estratégica alinhada com a direção. A sua chegada representa um passo importante para a consolidação e crescimento sustentado do nosso projeto desportivo"}]}, {"type": "p", "parts": [{"text": "Iniciamos, assim, um novo ciclo com confiança, responsabilidade e determinação, preparados para enfrentar os desafios futuros e continuar a elevar o nome do Damaiense"}]}, {"type": "p", "parts": [{"text": "#SomosDamaiense #Desde1938"}]}]'::jsonb,'published'),
  ('mensagem-pascoa-2026','Mensagem Páscoa 2026','Clube','/assets/7f9e413f355b561efcab64e3d009b81a.jpg','2026-04-05','[{"type": "p", "parts": [{"text": "O SF Damaiense deseja a todos os seus atletas, famílias, sócios, adeptos e parceiros uma Páscoa repleta de saúde, união e momentos de verdadeira partilha."}]}, {"type": "p", "parts": [{"text": "Que esta época especial simbolize renovação, esperança e motivação para continuarmos, juntos, a representar o clube com dedicação, respeito e um forte espírito de equipa."}]}, {"type": "p", "parts": [{"text": "Seguimos unidos, dentro e fora de campo, com o compromisso de crescer e honrar os valores que nos definem."}]}, {"type": "p", "parts": [{"text": "Feliz Páscoa!"}]}]'::jsonb,'published'),
  ('assembleia-geral-convocatoria','Assembleia Geral - Convocatória','Clube','/assets/49098648fb7d60d323204f2bafb40cd6.jpg','2026-03-28','[{"type": "p", "parts": [{"text": "O SF Damaiense informa todos os seus sócios que a Assembleia Geral terá lugar hoje, pelas 17h30."}]}, {"type": "p", "parts": [{"text": "A participação dos associados é de extrema importância, sendo fundamental para a definição do futuro e crescimento do clube."}]}, {"type": "p", "parts": [{"text": "A Direção apela à presença de todos os sócios neste momento relevante da vida do clube."}]}]'::jsonb,'published'),
  ('feliz-dia-do-pai','Feliz dia do Pai','Clube','/assets/05ad05171a090af6f8852f3e03d44b0b.jpg','2026-03-19','[{"type": "p", "parts": [{"text": "Hoje celebramos aqueles que, desde o primeiro momento, nos ensinaram muito mais do que palavras — ensinaram-nos a sentir, a viver e a acreditar."}]}, {"type": "p", "parts": [{"text": "Ser pai é representar força, dedicação e presença constante. É estar ao lado nos desafios e nas conquistas, dentro e fora de qualquer campo. É liderar pelo exemplo, inspirar com atitudes e transmitir valores que se carregam para toda a vida."}]}, {"type": "p", "parts": [{"text": "Ser pai também é cultivar uma paixão silenciosa, um orgulho que não precisa de explicação — apenas se sente. É construir laços, histórias e memórias que atravessam gerações."}]}, {"type": "p", "parts": [{"text": "A todos os pais que fazem parte da nossa comunidade, o nosso sincero agradecimento por caminharem connosco e ajudarem a dar sentido a tudo o que somos."}]}, {"type": "p", "parts": [{"text": "Feliz Dia do Pai. "}]}, {"type": "p", "parts": [{"text": "#SomosDamaiense"}]}]'::jsonb,'published'),
  ('patrono-damaiense-pascoa-cup','Patrono Damaiense Páscoa Cup','Formação','/assets/4aa4a45d62285887e59120b638882dc0.jpg','2026-03-12','[{"type": "p", "parts": [{"text": "Natural da Damaia, Diogo Prioste nunca escondeu o carinho pelo SF Damaiense. Mesmo sem nunca ter representado o clube, cresceu a assistir aos jogos e a viver de perto a paixão pelo futebol no nosso bairro."}]}, {"type": "p", "parts": [{"text": "Agora, como Capitão do SL Benfica B, aceitou sem hesitar o convite para ser Patrono Oficial da XI edição do Damaiense Páscoa Cup 2026."}]}, {"type": "p", "parts": [{"text": "Para o Diogo, este convite é um verdadeiro privilégio e também uma forma de reviver a infância, vendo os mais jovens espalhar talento dentro de campo… e quem sabe se entre eles não estará um futuro craque a seguir os seus passos."}]}, {"type": "p", "parts": [{"text": "O nosso muito obrigado ao Diogo por aceitar fazer parte desta edição!"}]}, {"type": "p", "parts": [{"text": "A Damaia orgulha-se de ti"}]}, {"type": "p", "parts": [{"text": "#PatronoOficial #DamaiensePascoaCup2026"}]}]'::jsonb,'published'),
  ('celebracao-dia-da-mulher','Celebração Dia da Mulher','Clube','/assets/7e097ec578ff17747fd20662427c4ed2.jpg','2026-03-08','[{"type": "p", "parts": [{"text": "Durante o fim de semana celebrámos o Dia da Mulher de uma forma muito especial"}]}, {"type": "p", "parts": [{"text": "Antes do início do jogo, os nossos jogadores entraram em campo acompanhados pelas “suas” mulheres, num gesto simbólico de respeito, reconhecimento e agradecimento a todas aquelas que fazem parte das nossas vidas e do nosso Damaiense"}]}, {"type": "p", "parts": [{"text": "Um pequeno momento, mas cheio de significado, para homenagear a força, a dedicação e a inspiração que as mulheres representam todos os dias."}]}, {"type": "p", "parts": [{"text": "Este foi um resumo do nosso grande Dia da Mulher no Damaiense"}]}]'::jsonb,'published'),
  ('andre-salvado-deixa-funcoes-no-sport-futebol-damaiense','André Salvado deixa funções no SF Damaiense','Clube','/assets/80966fafc93534d52886d222d3742aa3.jpg','2026-03-08','[{"type": "p", "parts": [{"text": "O SF Damaiense informa que André Salvado cessa hoje as suas funções como treinador da equipa sénior e coordenador de futebol do clube."}]}, {"type": "p", "parts": [{"text": "Esta decisão foi tomada por mútuo acordo e resulta exclusivamente de uma decisão pessoal do treinador, a qual o clube respeita na totalidade."}]}, {"type": "p", "parts": [{"text": "André Salvado deixa um legado marcante na história recente do Damaiense, tendo representado o clube com enorme dedicação ao longo de vários anos e em diferentes funções. Iniciou o seu percurso como jogador, assumiu posteriormente responsabilidades como treinador da formação, coordenador do futebol e, mais recentemente, liderou a nossa equipa sénior."}]}, {"type": "p", "parts": [{"text": "Ao longo deste percurso, destacou-se pelo profissionalismo, compromisso e profunda ligação ao clube, contribuindo de forma significativa para o crescimento e afirmação do projeto desportivo do Damaiense."}]}, {"type": "p", "parts": [{"text": "O SF Damaiense agradece sinceramente todo o trabalho, dedicação e paixão demonstrados."}]}, {"type": "p", "parts": [{"text": "Desejamos ao André Salvado os maiores sucessos pessoais e profissionais para o futuro."}]}, {"type": "p", "parts": [{"text": "Esta será sempre a tua casa."}]}, {"type": "p", "parts": [{"text": "Obrigado por tudo, Mister."}]}]'::jsonb,'published'),
  ('xi-edicao-damaiense-pascoa-cup-2026','XI Edição Damaiense Páscoa CUP 2026','Formação','/assets/d44e49cff902050ffc80363b25f54567.jpg','2026-02-24','[{"type": "p", "parts": [{"text": "A XI Edição do Damaiense Páscoa CUP 2026 já tem data marcada e promete voltar a ser um dos grandes momentos do futebol de formação nesta época desportiva."}]}, {"type": "p", "parts": [{"text": "O torneio irá decorrer entre 30 de março e 4 de abril de 2026, reunindo alguns dos clubes mais emblemáticos da região e proporcionando uma semana repleta de competição, fair-play, convívio e paixão pelo futebol."}]}, {"type": "p", "parts": [{"text": "Escalões em Competição: Petizes, Traquinas, Benjamins, Infantis"}]}, {"type": "p", "parts": [{"text": "Durante seis dias, jovens atletas terão a oportunidade de competir num ambiente organizado, competitivo e formativo, promovendo os valores do desporto, da amizade e do respeito."}]}, {"type": "p", "parts": [{"text": "Equipas Confirmadas"}]}, {"type": "p", "parts": [{"text": "A edição de 2026 contará já com as seguintes equipas confirmadas:"}]}, {"type": "p", "parts": [{"text": "Clube de Futebol Benfica (Fofó)"}]}, {"type": "p", "parts": [{"text": "Estrela da Amadora"}]}, {"type": "p", "parts": [{"text": "Real Massamá"}]}, {"type": "p", "parts": [{"text": "Sport Lisboa Benfica"}]}, {"type": "p", "parts": [{"text": "Futebol Clube Outurela"}]}, {"type": "p", "parts": [{"text": "REP Tenente Valdez"}]}, {"type": "p", "parts": [{"text": "CD Olivais e Moscavide"}]}, {"type": "p", "parts": [{"text": "Casa Pia"}]}, {"type": "p", "parts": [{"text": "UDR Algés"}]}, {"type": "p", "parts": [{"text": "Mais equipas poderão ser anunciadas brevemente."}]}, {"type": "p", "parts": [{"text": "O Damaiense Páscoa CUP continua a afirmar-se como uma referência no futebol jovem, proporcionando uma experiência única a atletas, treinadores, famílias e adeptos."}]}, {"type": "p", "parts": [{"text": "Fique atento às próximas novidades, calendário de jogos e informações adicionais que serão divulgadas em breve."}]}, {"type": "p", "parts": [{"text": "30 de março a 4 de abril de 2026"}]}, {"type": "p", "parts": [{"text": "XI Damaiense Páscoa CUP 2026"}]}, {"type": "p", "parts": [{"text": "Ainda vais a tempo de garantir o teu lugar no melhor torneio da Páscoa! "}]}, {"type": "p", "parts": [{"text": "Garante já a tua inscrição para torneios@sfdamaiense.pt "}]}]'::jsonb,'published'),
  ('joao-lavado-e-o-novo-presidente-do-sport-futebol-damaiense','João Lavado é o novo Presidente do SF Damaiense','Clube','/assets/190faba7b878838a8bb9c0438bcf85eb.jpg','2026-02-02','[{"type": "p", "parts": [{"text": "O SF Damaiense anuncia, com grande entusiasmo, a eleição de João Lavado como novo Presidente do clube."}]}, {"type": "p", "parts": [{"text": "Assumindo esta função com um profundo sentido de responsabilidade, dedicação e paixão pelo Damaiense, João Lavado inicia um novo ciclo de liderança com o compromisso de deixar uma marca duradoura na história do clube. A sua presidência tem como pilares a excelência desportiva, o fortalecimento da estrutura do clube e a promoção do bem-estar de todos os atletas, sócios e colaboradores."}]}, {"type": "p", "parts": [{"text": "A visão do novo Presidente assenta no crescimento sustentável do SF Damaiense, na superação contínua de desafios e na valorização do espírito de família que sempre caracterizou o clube. Acreditando que o sucesso se constrói em conjunto, João Lavado reforça a importância da união entre direção, atletas, equipa técnica, sócios e adeptos."}]}, {"type": "p", "parts": [{"text": "Este novo capítulo representa uma oportunidade para consolidar valores, honrar a história do Damaiense e projetar o clube para um futuro ainda mais ambicioso."}]}, {"type": "p", "parts": [{"text": "O SF Damaiense expressa o seu mais profundo agradecimento à Presidente cessante Sónia Santos e a toda a sua Direção pelo trabalho, dedicação e compromisso demonstrados ao longo dos dois mandatos ao serviço do nosso clube."}]}, {"type": "p", "parts": [{"text": "Viva o Damaiense! "}]}, {"type": "p", "parts": [{"text": "Desde 1938, a dignificar e honrar o nosso emblema."}]}]'::jsonb,'published'),
  ('88-anos-de-historia','88 Anos de História','Clube','/assets/f7c6c4424d4b8208f42eef2d52d69ec5.jpg','2026-01-01','[{"type": "p", "parts": [{"text": "88 Anos de História! Um Orgulho que Atravessa Gerações."}]}, {"type": "p", "parts": [{"text": "Desde 1938, o SF Damaiense é mais do que um clube — é identidade, paixão e pertença. São 88 anos de história feitos de conquistas, desafios superados e de um amor incondicional às nossas cores."}]}, {"type": "p", "parts": [{"text": "Cada jogo, cada atleta, cada sócio e adepto ajudaram a construir este legado que atravessa gerações e continua vivo dentro e fora do campo. O passado honra-nos, o presente move-nos e o futuro chama-nos a continuar a escrever a nossa história com ambição, união e respeito pelos valores que nos definem."}]}, {"type": "p", "parts": [{"text": "O Damaiense não é apenas o que foi."}]}, {"type": "p", "parts": [{"text": "É tudo o que somos."}]}, {"type": "p", "parts": [{"text": "E tudo o que ainda vamos ser."}]}, {"type": "p", "parts": [{"text": "Desde 1938. Sempre Damaiense."}]}]'::jsonb,'published'),
  ('feliz-natal','Feliz Natal','Clube','/assets/c0b9399350acde1928ab5e83297decd4.jpg','2025-12-15','[{"type": "p", "parts": [{"text": "O Sport Futebol Damaiense deseja a todos os seus atletas, treinadores, dirigentes, sócios, adeptos e parceiros um Santo e Feliz Natal."}]}, {"type": "p", "parts": [{"text": "Que esta época seja vivida com união, alegria e espírito de equipa — os mesmos valores que nos movem diariamente dentro e fora do campo. Que o novo ano traga saúde, sucesso desportivo e muitas conquistas, sempre com o Damaiense no coração. "}]}, {"type": "p", "parts": [{"text": "Obrigado por fazerem parte da nossa família."}]}, {"type": "p", "parts": [{"text": "Juntos, continuamos a construir o futuro!  "}]}]'::jsonb,'published'),
  ('no-damaiense-jogamos-juntos-e-fora-do-relvado','No Damaiense, jogamos juntos e fora do relvado','Clube','/assets/d8eee4d6a81af3f034c6e0bb65266030.jpg','2025-10-08','[{"type": "p", "parts": [{"text": "Outubro Rosa: A Prevenção é a Melhor Jogada!"}]}, {"type": "p", "parts": [{"text": "Neste Outubro Rosa, lembramos que a prevenção é a melhor jogada — e que juntos podemos vencer o cancro da mama!"}]}, {"type": "p", "parts": [{"text": "Durante este mês, multiplicam-se as ações de sensibilização que têm como objetivo alertar para a importância do diagnóstico precoce e para os cuidados com a saúde da mulher."}]}, {"type": "p", "parts": [{"text": "O cancro da mama é um dos tipos mais comuns entre as mulheres, mas quando detetado a tempo, as hipóteses de cura podem ultrapassar os 90%. Por isso, é fundamental realizar o autoexame regularmente e fazer mamografias de rotina conforme a orientação médica."}]}, {"type": "p", "parts": [{"text": "Mais do que uma cor ou um símbolo, o Outubro Rosa é um movimento de união, empatia e força."}]}, {"type": "p", "parts": [{"text": "Use o laço rosa, partilhe informação e incentive outras mulheres a cuidarem de si — porque cada gesto conta, e juntos podemos lutar contra o cancro da mama!"}]}]'::jsonb,'published'),
  ('esta-a-chegar-a-damaiense-minifoot-league-2025','Está a chegar a Damaiense Minifoot League 2025!','Formação','/assets/51ea0b37af3a1c4c015138bddffd79e2.jpg','2025-09-15','[{"type": "p", "parts": [{"text": "A partir do dia 26 de outubro, todos os meses o Complexo Desportivo do SF Damaiense será palco de uma competição especial, onde a paixão pelo futebol e a alegria das crianças são os verdadeiros protagonistas."}]}, {"type": "p", "parts": [{"text": "Petizes e Traquinas vão viver a magia do futebol em mais uma grande competição organizada pelo nosso clube, que promete emoção, fair play e muitos golos!"}]}, {"type": "p", "parts": [{"text": "Escalão Petizes"}]}, {"type": "p", "parts": [{"text": "SF Damaiense"}]}, {"type": "p", "parts": [{"text": "SU Sintrense"}]}, {"type": "p", "parts": [{"text": "“Os Fixes”"}]}, {"type": "p", "parts": [{"text": "Os Belenenses (Mem Martins)"}]}, {"type": "p", "parts": [{"text": "Os Belenenses (Lisboa Centro)"}]}, {"type": "p", "parts": [{"text": "EF Misericórdia"}]}, {"type": "p", "parts": [{"text": "Mem Martins SC"}]}, {"type": "p", "parts": [{"text": "Estrela da Amadora"}]}, {"type": "p", "parts": [{"text": "Escalão Traquinas"}]}, {"type": "p", "parts": [{"text": "SL Benfica"}]}, {"type": "p", "parts": [{"text": "Mercês"}]}, {"type": "p", "parts": [{"text": "O futebol de formação é futuro, é paixão e é família. Vem apoiar os nossos pequenos grandes jogadores e sentir de perto a energia da Damaiense Minifoot League 2025!"}]}, {"type": "p", "parts": [{"text": "#SomosDamaiense #Desde1938 #AcademiaDamaiense #FamiliaDamaiense #MinifootLeague"}]}]'::jsonb,'published'),
  ('nota-de-pesar-sf-damaiense','Nota de Pesar – SF Damaiense','Clube','/assets/709db4da0e9e8aceab9d52b3ca24618b.jpg','2025-09-08','[{"type": "p", "parts": [{"text": "O SF Damaiense manifesta o seu mais profundo pesar pelo falecimento do jovem atleta Sub-8 do Boavista Futebol Clube."}]}, {"type": "p", "parts": [{"text": "Neste momento de imensa dor, endereçamos as nossas mais sentidas condolências à família, amigos, colegas de equipa e a toda a estrutura do Boavista FC, desejando força e união para enfrentar esta perda irreparável."}]}, {"type": "p", "parts": [{"text": "O futebol é paixão, é união, é partilha — e hoje estamos todos juntos na dor."}]}, {"type": "p", "parts": [{"text": "#ForçaBoavista #SomosDamaiense"}]}]'::jsonb,'published'),
  ('plantel-oficial-202526-sport-futebol-damaiense','Plantel Oficial 2025/26 – SF Damaiense','Futebol','/assets/31b415e04e5564923fb5926a056c933c.jpg','2025-09-06','[{"type": "p", "parts": [{"text": "O SF Damaiense apresenta oficialmente o plantel sénior para a época 2025/2026!"}]}, {"type": "p", "parts": [{"text": "Um grupo que junta experiência, juventude e ambição, pronto para vestir com orgulho as cores do nosso clube e lutar em cada jornada."}]}, {"type": "p", "parts": [{"text": "Na fotografia oficial da época estão representados não só os nossos jogadores, mas também toda a equipa técnica e staff de apoio, elementos fundamentais para que nada falte dentro e fora de campo."}]}, {"type": "p", "parts": [{"text": "O Damaiense é mais do que uma equipa: é uma família. Unidos pelo mesmo objetivo, preparados para enfrentar cada desafio e escrever mais um capítulo da nossa história desde 1938."}]}, {"type": "p", "parts": [{"text": "Esta é a nossa força. Este é o nosso plantel. Este é o Damaiense!"}]}, {"type": "p", "parts": [{"text": "#SomosDamaiense #Desde1938 #FamiliaDamaiense #Epoca2025_26"}]}]'::jsonb,'published'),
  ('a-nossa-equipa-tecnica-202526','A Nossa Equipa Técnica 2025/26','Futebol','/assets/6e9f8fc749b951317f73e47d96b72f94.jpg','2025-09-04','[{"type": "p", "parts": [{"text": "Experiência, energia e compromisso. É com estes valores que a equipa técnica sénior do SF Damaiense encara a nova época desportiva, preparada para enfrentar desafios e conquistar objetivos."}]}, {"type": "p", "parts": [{"text": "No comando estará o treinador André Salvado, que contará com o apoio de uma equipa de adjuntos de excelência:"}]}, {"type": "p", "parts": [{"text": "Vasco Augusto"}]}, {"type": "p", "parts": [{"text": "João Coimbra"}]}, {"type": "p", "parts": [{"text": "André Couto"}]}, {"type": "p", "parts": [{"text": "André Luz"}]}, {"type": "p", "parts": [{"text": "Pedro Abrantes"}]}, {"type": "p", "parts": [{"text": "A equipa técnica ficará ainda mais forte com o trabalho fundamental do fisioterapeuta Diogo Gonçalves, garantindo que os nossos jogadores se mantêm preparados e em plena forma ao longo da época."}]}, {"type": "p", "parts": [{"text": "Mais do que treinadores, são líderes, mentores e parte essencial da Família Damaiense. Porque a força de um clube não está apenas no relvado, mas também em quem o orienta fora dele."}]}, {"type": "p", "parts": [{"text": "Juntos, carregamos o Damaiense para mais uma época inesquecível!"}]}, {"type": "p", "parts": [{"text": "#SomosDamaiense #Desde1938 #FamiliaDamaiense"}]}]'::jsonb,'published'),
  ('damaiense-cup-2025-sub-17','Damaiense Cup 2025 · Sub-17','Formação','/assets/550a2b5bb13868c08a24c25027bdd85e.jpg','2025-09-03','[{"type": "p", "parts": [{"text": "O Futebol de Formação está de volta em grande!"}]}, {"type": "p", "parts": [{"text": "No próximo 20 de setembro, o Complexo Desportivo Eugénia e Joaquim Cannas da Silva será palco da Damaiense Cup 2025 Sub-17, um torneio que promete muita emoção, talento e rivalidade saudável dentro das quatro linhas."}]}, {"type": "p", "parts": [{"text": "Grupo A"}]}, {"type": "p", "parts": [{"text": "SF Damaiense B"}]}, {"type": "p", "parts": [{"text": "SC Lourinhanense"}]}, {"type": "p", "parts": [{"text": "CD Pinhalnovense"}]}, {"type": "p", "parts": [{"text": "Grupo B"}]}, {"type": "p", "parts": [{"text": "SF Damaiense A"}]}, {"type": "p", "parts": [{"text": "AL Cartaxo"}]}, {"type": "p", "parts": [{"text": "GD Coruchense"}]}, {"type": "p", "parts": [{"text": "Com a participação de equipas de referência no futebol jovem, esta edição traz ainda um patrono de luxo: Jorge Andrade, ex-internacional português, que dará ainda mais brilho à competição."}]}, {"type": "p", "parts": [{"text": "Um agradecimento especial a todos os patrocinadores, que tornam possível este grande evento e que, tal como nós, vão a jogo connosco"}]}, {"type": "p", "parts": [{"text": "A Damaiense Cup 2025 Sub-17 não é apenas um torneio: é uma celebração da paixão pelo futebol, da dedicação dos jovens atletas e da força do desporto em comunidade."}]}, {"type": "p", "parts": [{"text": "Marca já na tua agenda e vem viver connosco esta festa do futebol de formação!"}]}, {"type": "p", "parts": [{"text": "#DamaienseCup2025 #Sub17 #SFDamaiense #SomosDamaiense #Desde1938 #ADNDamaiense"}]}]'::jsonb,'published'),
  ('um-agradecimento-especial-ao-nosso-patrono','Um agradecimento especial ao nosso Patrono','Clube','/assets/f0821ec183276c93305223a856337ade.jpg','2025-04-21','[{"type": "p", "parts": [{"text": "Um agradecimento especial ao nosso Patrono Oficial da X Edição do Torneio : Geovany Quenda"}]}, {"type": "p", "parts": [{"text": "Foi com um enorme prazer que recebemos nesta que continua a ser a sua casa o nosso ex-atleta e atual jogador do Sporting Clube de Portugal e Seleção de Portugal A."}]}, {"type": "p", "parts": [{"text": "Serás sempre bem-vindo!"}]}, {"type": "p", "parts": [{"text": "O nosso Muito Obrigado"}]}]'::jsonb,'published'),
  ('classificacoes-finais-10a-damaiense-pascoa-cup','Classificações finais - 10ª Damaiense Páscoa Cup','Formação','/assets/64a35f3d104b0b9df1a43f3fc5f830b4.jpg','2025-04-20','[{"type": "p", "parts": [{"text": "Petizes"}]}, {"type": "p", "parts": [{"text": "Sporting CP"}]}, {"type": "p", "parts": [{"text": "SL Benfica"}]}, {"type": "p", "parts": [{"text": "Futebol Benfica"}]}, {"type": "p", "parts": [{"text": "Melhor Jogador : Rodrigo Pires (SL Benfica)"}]}, {"type": "p", "parts": [{"text": "Melhor Marcador : Francisco Simão (Sporting CP)"}]}, {"type": "p", "parts": [{"text": "Melhor GR : Lucas Lima (Sporting CP)"}]}, {"type": "p", "parts": [{"text": "Traquinas"}]}, {"type": "p", "parts": [{"text": "Real SC"}]}, {"type": "p", "parts": [{"text": "Melhor Jogador : Benjamin Bernardes (Os Fixes)"}]}, {"type": "p", "parts": [{"text": "Melhor Marcador : Liam Dabó (Sporting CP)"}]}, {"type": "p", "parts": [{"text": "Melhor GR: Enzo Delgado (Futebol Benfica)"}]}, {"type": "p", "parts": [{"text": "Benjamins E1"}]}, {"type": "p", "parts": [{"text": "Casa Pia AC"}]}, {"type": "p", "parts": [{"text": "SL Olivais"}]}, {"type": "p", "parts": [{"text": "Outurela"}]}, {"type": "p", "parts": [{"text": "Melhor Jogador : Miguel Duarte (Outurela)"}]}, {"type": "p", "parts": [{"text": "Melhor Marcador : Tomás Oliveira (Outurela)"}]}, {"type": "p", "parts": [{"text": "Melhor GR: Davi Silva (Casa Pia AC)"}]}, {"type": "p", "parts": [{"text": "Benjamins E2"}]}, {"type": "p", "parts": [{"text": "Damaiense Red"}]}, {"type": "p", "parts": [{"text": "Melhor Jogador : Rodrigo Oliveira (Sporting CP)"}]}, {"type": "p", "parts": [{"text": "Melhor Marcador : Malik Baio (Sporting CP)"}]}, {"type": "p", "parts": [{"text": "Melhor GR: Rodrigo Pereira (Damaiense Red)"}]}, {"type": "p", "parts": [{"text": "Infantis D1"}]}, {"type": "p", "parts": [{"text": "Damaiense"}]}, {"type": "p", "parts": [{"text": "Melhor Jogador : Zacarias Lopes (Casa Pia AC)"}]}, {"type": "p", "parts": [{"text": "Melhor Marcador : Cláudio Grosa (Damaiense)"}]}, {"type": "p", "parts": [{"text": "Melhor GR: Bernardo Costa (Damaiense)"}]}, {"type": "p", "parts": [{"text": "Infantis D2"}]}, {"type": "p", "parts": [{"text": "Estrela Amadora"}]}, {"type": "p", "parts": [{"text": "Melhor Jogador : Kevin Silva (SL Benfica)"}]}, {"type": "p", "parts": [{"text": "Melhor Marcador : Rafael Fonseca (SL Benfica)"}]}, {"type": "p", "parts": [{"text": "Melhor GR: Gonçalo Ferreira (Estrela Amadora)"}]}, {"type": "p", "parts": [{"text": "Link Instagram"}]}, {"type": "p", "parts": [{"text": "#DamaiensePascoaCup2025"}]}]'::jsonb,'published'),
  ('reportagem-com-geovany-quenda','Reportagem com Geovany Quenda','Formação','/assets/1bf8d4872dc1163e74f5a8bb33c645d9.jpg','2025-04-08','[{"type": "p", "parts": [{"text": "Com a palavra, o nosso @gquenda07"}]}, {"type": "p", "parts": [{"text": "A jovem estrela da Seleção Nacional, que deu início à sua brilhante jornada a defender as cores do Damaiense, regressou às nossas instalações para partilhar o seu carinho pelo clube e falar sobre a 10ª da edição da Damaiense Páscoa CUP, torneio do qual é Patrono Oficial!"}]}, {"type": "p", "parts": [{"text": "Podem aceder ao link do nosso instagram para ver a reportagem: http://www.instagram.com/p/DILuQWBC6vG/"}]}, {"type": "p", "parts": [{"text": "Carrega Damaiense!!"}]}, {"type": "p", "parts": [{"text": "#SomosDamaiense #Desde1938 #FamiliaDamaiense #AcademiaDamaiense"}]}, {"type": "p", "parts": [{"text": "#ForçaDamaiense #quenda #seleção #portugal"}]}]'::jsonb,'published'),
  ('parceiros-oficiais-10a-edicao-da-damaiense-pascoa-cup','Parceiros Oficiais 10ª edição da Damaiense Páscoa CUP','Clube','/assets/51caaa1fd9ecd9cc77b2fd1a665cac33.jpg','2025-04-04','[{"type": "p", "parts": [{"text": "A 10ª edição da Damaiense Páscoa Cup está prestes a começar e nada disto seria possível sem o apoio dos nossos patrocinadores!"}]}, {"type": "p", "parts": [{"text": "Não percas, de 14 a 19 de abril, voltamos a fazer história. O futuro do futebol começa aqui!!"}]}, {"type": "p", "parts": [{"text": "#AcademiaDamaiense #SomosDamaiense #Desde1938 #FamiliaDamaiense"}]}]'::jsonb,'published'),
  ('10a-edicao-da-damaiense-pascoa-cup','10ª edição da Damaiense Páscoa CUP','Formação','/assets/c09b6b7e99d39c8cf01dcb156490d928.jpg','2025-02-18','[{"type": "p", "parts": [{"text": "Geovany Quenda, ex-atleta do SFD, é o Patrono Oficial da 10ª edição da Damaiense Páscoa CUP"}]}, {"type": "p", "parts": [{"text": "Uma honra contar com a presença de quem tanto representa o espirito do futebol!"}]}, {"type": "p", "parts": [{"text": "Este torneio reunirá algumas das principais equipas de futebol jovem do país, proporcionando um ambiente de competição saudável, convívio e desenvolvimento para crianças dos escalões de Petizes, Traquinas, Benjamins e Infantis."}]}, {"type": "p", "parts": [{"text": "Com a participação de clubes renomados como Sporting CP, Estrela da Amadora, Casa Pia e Futebol Benfica, entre outros, o Páscoa Cup 2025 será um palco de grandes momentos para as futuras estrelas do futebol."}]}, {"type": "p", "parts": [{"text": "Data: 14 a 19 de Abril de 2025"}]}, {"type": "p", "parts": [{"text": "Horário: Das 9h às 18h"}]}, {"type": "p", "parts": [{"text": "Local:  Complexo Desportivo Eugénia e Joaquim Cannas da Silva"}]}]'::jsonb,'published'),
  ('patrono-oficial-sf-damaiense-pascoa-cup-2024','Patrono Oficial SF Damaiense Páscoa Cup 2024','Formação','/assets/9e315c16622771503c63e3864069e821.jpg','2024-03-15','[{"type": "p", "parts": [{"text": "O Ex-atleta do SF Damaiense e atual jogador do SL Benfica e Seleção de Cabo Verde é o Patrono Oficial do torneio SFD Damaiense Páscoa Cup 2024."}]}]'::jsonb,'published'),
  ('sf-damaiense-pascoa-cup-2024','SF Damaiense Páscoa Cup 2024','Formação','/assets/96b744de65b0f28d80237c453f9ad264.jpg','2023-12-07','[{"type": "p", "parts": [{"text": "O nosso SF Damaiense Páscoa Cup estará de volta em 2024"}]}, {"type": "p", "parts": [{"text": "Inscrições abertas para o melhor torneio de Páscoa em vários escalões de formação."}]}, {"type": "p", "parts": [{"text": "Inscrições"}]}, {"type": "p", "parts": [{"text": "Luís Octaviano"}]}, {"type": "p", "parts": [{"text": "962 761 449"}]}, {"type": "p", "parts": [{"text": "luis.octaviano@sfdamaiense.pt"}]}, {"type": "p", "parts": [{"text": "Vasco Silveira"}]}, {"type": "p", "parts": [{"text": "912 148 688"}]}, {"type": "p", "parts": [{"text": "coordenacao@sfdamaiense.pt"}]}, {"type": "p", "parts": [{"text": "João Felício"}]}, {"type": "p", "parts": [{"text": "934 596 125"}]}, {"type": "p", "parts": [{"text": "joao.felicio@sfdamaiense.pt"}]}]'::jsonb,'published');
